from qiskit import transpile
from qiskit_aer import AerSimulator

def run_and_analyze(circuit, aer_sim):
    circuit = transpile(circuit, aer_sim)
    result = aer_sim.run(circuit, shots=2048).result()
    counts = result.get_counts()

    fx_to_x = {}
    for key in counts.keys():
        key = key.replace(" ", "")
        if len(key) != 10:
            continue
        fx_bin = key[:5]
        x_bin = key[5:]
        x_val = int(x_bin, 2)
        if x_val >= 27:
            continue

        t0 = x_val % 3
        t1 = (x_val // 3) % 3
        t2 = (x_val // 9) % 3
        t_tuple = (t2, t1, t0)

        if fx_bin not in fx_to_x:
            fx_to_x[fx_bin] = []
        if t_tuple not in fx_to_x[fx_bin]:
            fx_to_x[fx_bin].append(t_tuple)

    for fx, x_list in fx_to_x.items():
        if len(x_list) >= 3:
            x1 = x_list[0]
            x2 = x_list[1]
            diff = [(a - b) % 3 for a, b in zip(x2, x1)]
            first_nonzero = next((d for d in diff if d != 0), None)
            if first_nonzero == 2:
                diff = [(d * 2) % 3 for d in diff]
            return "".join(map(str, diff))

    return "000"
"""
